const byId = new Map(locationPages.map((page) => [page.id, page]));
const bySegments = new Map(locationPages.map((page) => [page.segments.join('/'), page]));

export function getLocationStaticSegments(): string[][] {
  return locationPages.filter((page) => page.segments.length > 0).map((page) => page.segments);
}

export function getLocationDefinitionById(id: string): LocationPageDefinition | undefined {
  return byId.get(id);
}

export function getLocationDefinitionBySegments(segments: string[]): LocationPageDefinition | undefined {
  return bySegments.get(segments.join('/'));
}

export function localizeLocationPage(page: LocationPageDefinition, locale: SiteLocale): LocalizedLocationPage {
  return {
    ...page,
    name: page.name[locale], shortName: page.shortName[locale], eyebrow: page.eyebrow[locale],
    seo: { title: page.seo.title[locale], description: page.seo.description[locale], primaryKeyword: page.seo.primaryKeyword[locale], secondaryKeywords: page.seo.secondaryKeywords[locale], imageAlt: page.seo.imageAlt[locale] },
    heroTitle: page.heroTitle[locale], heroDescription: page.heroDescription[locale], trustPoints: page.trustPoints[locale],
    introductionTitle: page.introductionTitle[locale], introduction: page.introduction[locale],
    servicesTitle: page.servicesTitle[locale], servicesDescription: page.servicesDescription[locale], services: page.services.map((item) => ({ ...item, title: item.title[locale], description: item.description[locale] })),
    subjectsTitle: page.subjectsTitle[locale], subjectsDescription: page.subjectsDescription[locale], subjects: page.subjects.map((item) => ({ ...item, label: item.label[locale], description: item.description[locale] })),
    curriculumTitle: page.curriculumTitle[locale], curriculumDescription: page.curriculumDescription[locale], curriculumPoints: page.curriculumPoints[locale],
    assessmentsTitle: page.assessmentsTitle[locale], assessmentsDescription: page.assessmentsDescription[locale], assessments: page.assessments.map((item) => ({ name: item.name[locale], description: item.description[locale] })),
    gradesTitle: page.gradesTitle[locale], gradesDescription: page.gradesDescription[locale], grades: page.grades.map((item) => ({ ...item, title: item.title[locale], description: item.description[locale] })),
    familyTitle: page.familyTitle[locale], familyDescription: page.familyDescription[locale], familyPoints: page.familyPoints[locale],
    localGuideTitle: page.localGuideTitle[locale], localGuideDescription: page.localGuideDescription[locale], localContext: page.localContext[locale],
    resources: page.resources.map((item) => ({ ...item, description: item.description[locale] })),
    faqTitle: page.faqTitle[locale], faqDescription: page.faqDescription[locale], faqs: page.faqs.map((item) => ({ question: item.question[locale], answer: item.answer[locale] })),
  };
}
